<script setup lang="ts">
import { onMounted,ref } from 'vue';
import { accessRequest,useAccessStore,type AccessUser,type Role } from '../stores/access';
const access=useAccessStore(),users=ref<AccessUser[]>([]),role=ref<Role>('editor'),code=ref(''),recovery=ref(''),saved=ref(false),busy=ref(false),error=ref(''),notice=ref('');
interface Policy{dailyCalls:number;userCalls:number;dailyBytes:number;concurrency:number}
const usage=ref<{policy:Policy;day:string;calls:number;inputBytes:number;globalCalls?:number}|null>(null),policy=ref<Policy>({dailyCalls:500,userCalls:200,dailyBytes:2000000,concurrency:2});
async function refresh(){usage.value=await accessRequest('usage');policy.value={...usage.value!.policy};if(access.admin)users.value=(await accessRequest<{users:AccessUser[]}>('access/users')).users;}
async function perform(fn:()=>Promise<void>){busy.value=true;error.value='';notice.value='';try{await fn();}catch(e){error.value=e instanceof Error?e.message:'No se pudo completar la acción.';}finally{busy.value=false;}}
async function invite(isRecovery=false){const result=await accessRequest<{code:string}>('access/invites',{role:isRecovery?'admin':role.value});if(isRecovery){recovery.value=result.code;saved.value=false;}else code.value=result.code;}
async function enable(){await accessRequest('access/enable',{recoveryToken:recovery.value});await access.initialize();notice.value='Modo compartido activo. Conserva el código de recuperación.';await refresh();}
async function update(user:AccessUser){await accessRequest('access/users/'+user.id,{role:user.role,disabled:!user.disabled});await refresh();}
async function renew(user:AccessUser){code.value=(await accessRequest<{code:string}>('access/users/'+user.id+'/invite',{})).code;notice.value='Nuevo código para '+user.name+'. Conserva su identidad y preferencias.';}
async function logout(){await accessRequest('access/logout',{});location.reload();}
onMounted(()=>perform(refresh));
</script>
<template><section class="panel access-panel"><div class="panel-toolbar"><span class="panel-title">ACCESO Y CONSUMO</span><span>{{ access.mode==='local'?'LOCAL':'COMPARTIDO' }}</span></div><h2>{{ access.user?.name??'Comandante' }}</h2><p>Rol: {{ access.user?.role??'admin' }}. Los proyectos y conversaciones pertenecen al espacio común; Bio-Armadura conserva preferencias personales.</p><p v-if="error" role="alert" class="library-error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
<button v-if="access.mode==='shared'" class="connection-action" :disabled="busy" @click="perform(logout)">Cerrar sesión</button>
<template v-if="access.admin"><h3>Invitaciones y permisos</h3><p>Administrador: conexiones IA, respaldos, accesos, consumo y publicación Git. Editor: proyectos, documentos y código. Lector: consulta del espacio y sus propios recordatorios.</p>
<template v-if="access.mode==='local'"><p>El modo local acepta acceso desde este equipo. Antes de compartir, guarda un código de recuperación. Fuera de localhost se requiere HTTPS; esta acción no publica el servicio. Los proyectos de código compartidos deben estar fuera de la carpeta de instalación de A.R.E.S.; configura sus raíces en el servidor.</p><button class="connection-action" :disabled="busy" @click="perform(()=>invite(true))">Preparar código de recuperación</button><template v-if="recovery"><label for="recovery-code">Código privado de recuperación (caduca en 24 horas)</label><input id="recovery-code" :value="recovery" readonly autocomplete="off"/><label><input v-model="saved" type="checkbox"/> Guardé este código en un lugar privado.</label><button class="connection-action" :disabled="busy||!saved" @click="perform(enable)">Activar accesos compartidos</button></template></template>
<template v-else><label for="invite-role">Rol de la invitación</label><select id="invite-role" v-model="role"><option value="viewer">Lector</option><option value="editor">Editor</option><option value="admin">Administrador</option></select><button class="connection-action" :disabled="busy" @click="perform(()=>invite())">Crear invitación</button><template v-if="code"><label for="invite-code">Código privado · un uso · 24 horas</label><input id="invite-code" :value="code" readonly autocomplete="off"/><p>Compártelo directamente con la persona elegida. No se puede volver a consultar.</p></template><ul class="access-users"><li v-for="user in users" :key="user.id"><span>{{ user.name }} · {{ user.role }} · {{ user.disabled?'revocado':'activo' }}</span><button v-if="!user.disabled" class="connection-action" :disabled="busy" @click="perform(()=>renew(user))">Renovar sesión</button><button v-if="user.id!==access.user?.id" class="connection-action" :disabled="busy" @click="perform(()=>update(user))">{{ user.disabled?'Reactivar':'Revocar acceso' }}</button></li></ul></template></template>
<h3>Consumo de IA</h3><p v-if="usage">Hoy ({{ usage.day }}, UTC): {{ usage.calls }} solicitudes · {{ usage.inputBytes.toLocaleString() }} bytes de entrada. <span v-if="usage.globalCalls!==undefined">Total del espacio: {{ usage.globalCalls }} solicitudes.</span></p><p>Cuenta generación, búsqueda, imágenes, audio y embeddings, incluidos intentos fallidos. Son topes locales de solicitudes y datos enviados, no un presupuesto monetario ni el saldo de Gemini/OpenRouter. Los proveedores pueden aplicar cuotas adicionales.</p>
<form v-if="access.admin" @submit.prevent="perform(async()=>{await accessRequest('usage/policy',policy);await refresh();notice='Límites guardados.';})"><label for="daily-calls">Solicitudes diarias del espacio</label><input id="daily-calls" v-model.number="policy.dailyCalls" type="number" min="1" max="10000" required/><label for="user-calls">Solicitudes diarias por usuario</label><input id="user-calls" v-model.number="policy.userCalls" type="number" min="1" max="10000" required/><label for="daily-bytes">Bytes diarios de entrada del espacio</label><input id="daily-bytes" v-model.number="policy.dailyBytes" type="number" min="1000" max="100000000" required/><label for="concurrency">Solicitudes simultáneas</label><input id="concurrency" v-model.number="policy.concurrency" type="number" min="1" max="10" required/><button class="connection-action" :disabled="busy">Guardar límites</button></form><button class="connection-action" :disabled="busy" @click="perform(refresh)">Actualizar consumo</button>
</section></template>
